const Button = ({ label, variant = 'primary', onClick, disabled, icon: Icon, className = '' }) => {
  const baseStyle = {
    height: '44px',
    borderRadius: 'var(--radius)',
    padding: '0 24px',
    fontFamily: 'var(--font-body)',
    fontWeight: 600,
    fontSize: '14px',
    display: 'inline-flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    cursor: disabled ? 'not-allowed' : 'pointer',
    transition: 'all 0.2s cubic-bezier(0.4, 0, 0.2, 1)',
    border: 'none',
    outline: 'none',
  };

  const variants = {
    primary: {
      backgroundColor: disabled ? 'var(--border)' : 'var(--nu-red)',
      color: disabled ? 'var(--text-tertiary)' : '#FFF',
    },
    secondary: {
      backgroundColor: 'transparent',
      color: disabled ? 'var(--text-tertiary)' : 'var(--text-secondary)',
      border: `1px solid ${disabled ? 'var(--border)' : 'var(--text-secondary)'}`,
    },
    text: {
      backgroundColor: 'transparent',
      color: disabled ? 'var(--text-tertiary)' : 'var(--nu-red)',
      padding: '0 8px',
    }
  };

  return (
    <button 
      style={{ ...baseStyle, ...variants[variant] }} 
      onClick={onClick} 
      disabled={disabled}
      className={`btn-${variant} ${className}`}
      onMouseOver={(e) => {
        if (!disabled && variant === 'primary') e.currentTarget.style.backgroundColor = 'var(--nu-red-deep)';
        if (!disabled && variant === 'secondary') e.currentTarget.style.backgroundColor = 'var(--surface)';
      }}
      onMouseOut={(e) => {
        if (!disabled && variant === 'primary') e.currentTarget.style.backgroundColor = 'var(--nu-red)';
        if (!disabled && variant === 'secondary') e.currentTarget.style.backgroundColor = 'transparent';
      }}
    >
      {label}
      {Icon && <Icon size={16} />}
    </button>
  );
};

const Card = ({ children, style, onClick, hoverable }) => (
  <div 
    style={{
      backgroundColor: 'var(--bg)',
      borderRadius: 'var(--card-radius)',
      border: '1px solid var(--border)',
      padding: '24px',
      cursor: onClick ? 'pointer' : 'default',
      transition: 'all 0.2s ease',
      ...style
    }}
    onClick={onClick}
    onMouseOver={(e) => {
      if (hoverable) {
        e.currentTarget.style.boxShadow = '0 4px 12px rgba(0,0,0,0.05)';
        e.currentTarget.style.borderColor = 'var(--text-tertiary)';
      }
    }}
    onMouseOut={(e) => {
      if (hoverable) {
        e.currentTarget.style.boxShadow = 'none';
        e.currentTarget.style.borderColor = 'var(--border)';
      }
    }}
  >
    {children}
  </div>
);

