      const angle = (Math.PI * 2 * i) / 6 - Math.PI / 2;
      return `${center + radius * val * Math.cos(angle)},${center + radius * val * Math.sin(angle)}`;
    }).join(' ');

    return (
      <div style={{ position: 'relative', width: size, height: size, margin: '0 auto 32px auto' }}>
