              [0,1,2,3,4,5].map(i => {
                const angle = (Math.PI * 2 * i) / 6 - Math.PI / 2;
                return `${center + radius * r * Math.cos(angle)},${center + radius * r * Math.sin(angle)}`;
              }).join(' ')
            } fill="none" stroke="var(--border)" strokeWidth="1" />
          ))}
          {/* Axes */}
          {[0,1,2,3,4,5].map(i => {
            const angle = (Math.PI * 2 * i) / 6 - Math.PI / 2;
            return <line key={i} x1={center} y1={center} x2={center + radius * Math.cos(angle)} y2={center + radius * Math.sin(angle)} stroke="var(--border)" strokeWidth="1" />
          })}
          {/* Data Polygon */}
          <motion.polygon 
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8, ease: "easeOut" }}
            points={points} 
            fill="rgba(200, 16, 46, 0.1)" 
