const CopilotComposer = ({ match, onNavigate, onSend }) => {
  const alum = SEED_ALUMNI.find(a => a.id === match.alumniId);
  const [draft, setDraft] = useState('');
  const [tone, setTone] = useState('warm'); // warm, balanced, professional
  const [loading, setLoading] = useState(true);
  const [guardrailStatus, setGuardrailStatus] = useState('pass');

  const fetchDraft = async (selectedTone) => {
    setLoading(true);
    try {
      const sys = "You are a Copilot drafting a peer-to-peer intro message. Keep it under 80 words. Return ONLY valid JSON: { draft_text: string }";
      const user = `Draft an intro from Maya to ${alum.name}. Shared struggle: Python week 4. Tone: ${selectedTone}.`;
      const res = await callAIWithVS(sys, user);
      const parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
      setDraft(parsed.draft_text);
    } catch (e) {
      setDraft(`Hi ${alum.name.split(' ')[0]}, I'm a first-year in CS and I saw we both hit a wall with Python in week 4. I'd love to hear how you navigated it.`);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { fetchDraft(tone); }, [tone]);

  const handleSend = async () => {
    setGuardrailStatus('checking');
    try {
      const sys = "You are a safety guardrail. Scan the message. Return ONLY valid JSON: { decision: 'pass'|'hard-block' }";
      const res = await callAIWithFallback(sys, `Analyze: ${draft}`);
      const parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
      if (parsed.decision === 'pass') {
        onSend(draft);
        onNavigate('active_teams_thread');
      } else {
        setGuardrailStatus('blocked');
      }
    } catch (e) {
      // Fallback to pass for demo continuity
      onSend(draft);
      onNavigate('active_teams_thread');
    }
  };

  return (
    <div style={{ padding: '32px', maxWidth: '800px', margin: '0 auto' }}>
      <Card style={{ padding: 0, overflow: 'hidden' }}>
        <div style={{ padding: '24px', borderBottom: '1px solid var(--border)', backgroundColor: 'var(--surface)', display: 'flex', alignItems: 'center', gap: '12px' }}>
          <lucide.Sparkles color="var(--nu-red)" size={24} />
          <h2 style={{ margin: 0, fontFamily: 'var(--font-display)', fontSize: '20px' }}>Draft your intro to {alum.name.split(' ')[0]}</h2>
        </div>

        <div style={{ padding: '24px' }}>
          <div style={{ position: 'relative', marginBottom: '24px' }}>
            <textarea 
              value={draft}
              onChange={(e) => setDraft(e.target.value)}
              style={{ 
                width: '100%', height: '160px', padding: '16px', borderRadius: 'var(--radius)', 
                border: `1px solid ${guardrailStatus === 'blocked' ? 'var(--nu-red)' : 'var(--border)'}`, 
                fontFamily: 'var(--font-body)', fontSize: '16px', lineHeight: 1.5, resize: 'none',
                opacity: loading ? 0.5 : 1, transition: 'opacity 0.3s', boxSizing: 'border-box'
              }}
            />
            {loading && <div style={{ position: 'absolute', top: '50%', left: '50%', transform: 'translate(-50%, -50%)' }}><Skeleton width="24px" height="24px" style={{ borderRadius: '50%' }} /></div>}
          </div>

          {guardrailStatus === 'blocked' && (
            <div style={{ color: 'var(--nu-red)', fontSize: '14px', marginBottom: '16px', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <lucide.AlertTriangle size={16} /> Message flagged for review. Please adjust tone.
            </div>
          )}

          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', backgroundColor: 'var(--surface)', padding: '16px', borderRadius: 'var(--radius)' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '16px', flex: 1 }}>
              <span style={{ fontSize: '14px', color: 'var(--text-secondary)', fontWeight: 600 }}>Tone</span>
              <input 
                type="range" min="0" max="2" step="1" 
                value={tone === 'warm' ? 0 : tone === 'balanced' ? 1 : 2}
                onChange={(e) => {
                  const val = parseInt(e.target.value);
                  setTone(val === 0 ? 'warm' : val === 1 ? 'balanced' : 'professional');
                }}
                style={{ flex: 1, maxWidth: '200px', accentColor: 'var(--nu-red)' }}
              />
              <span style={{ fontSize: '14px', color: 'var(--text-secondary)', width: '80px' }}>
                {tone.charAt(0).toUpperCase() + tone.slice(1)}
              </span>
            </div>
            <Button variant="text" label="Show 2 alternates" onClick={() => fetchDraft(tone)} icon={lucide.RefreshCw} />
          </div>
        </div>

        <div style={{ padding: '24px', borderTop: '1px solid var(--border)', display: 'flex', justifyContent: 'flex-end', gap: '12px' }}>
          <Button variant="secondary" label="Regenerate" onClick={() => fetchDraft(tone)} disabled={loading} />
          <Button label="Send Message" onClick={handleSend} disabled={loading || guardrailStatus === 'blocked'} icon={lucide.Send} />
        </div>
      </Card>
    </div>
  );
};

const ActiveTeamsThread = ({ match, messages, onNewMessage, onNavigate }) => {
  const alum = SEED_ALUMNI.find(a => a.id === match.alumniId);
  const [draft, setDraft] = useState('');
  const [suggestions, setSuggestions] = useState([]);
  const [oppDetected, setOppDetected] = useState(false);
  const messagesEndRef = useRef(null);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  // Simulate Sarah's reply if only Maya has spoken
  useEffect(() => {
    if (messages.length === 1 && messages[0].from === 'Maya') {
      const timer = setTimeout(() => {
        const reply = "Hi Maya! Yes, CS 2500 was brutal. Happy to chat. Actually, my team at Cordial is hiring co-ops right now.";
        onNewMessage({ from: alum.name.split(' ')[0], text: reply, timestamp: new Date().toISOString(), copilotAssisted: false });
      }, 3000);
      return () => clearTimeout(timer);
    }
  }, [messages, alum.name, onNewMessage]);

  // Trigger AI Suggester & Extractor when Sarah replies
  useEffect(() => {
    const lastMsg = messages[messages.length - 1];
    if (lastMsg && lastMsg.from !== 'Maya') {
      const fetchSuggestions = async () => {
        try {
          const sys = "You are a conversation facilitator. Suggest 3 short replies for the student. Return ONLY valid JSON array of strings.";
          const res = await callAIWithVS(sys, `Thread: ${JSON.stringify(messages.slice(-3))}`);
          setSuggestions(JSON.parse(res.text.replace(/```json|```/g, '')));
        } catch (e) {
          setSuggestions(["That sounds great, when are you free?", "I'd love to hear more about Cordial.", "Thanks! How did you get past the week 4 wall?"]);
        }
      };

      const extractOpp = async () => {
        try {
          const sys = "Extract job opportunities. Return ONLY valid JSON: { opportunity_detected: boolean }";
          const res = await callAIWithFallback(sys, `Message: ${lastMsg.text}`);
          const parsed = JSON.parse(res.text.replace(/```json|```/g, ''));
          if (parsed.opportunity_detected) setOppDetected(true);
        } catch (e) {
          if (lastMsg.text.includes('hiring')) setOppDetected(true);
        }
      };

      fetchSuggestions();
      extractOpp();
    } else {
      setSuggestions([]);
    }
  }, [messages]);

  const handleSend = () => {
    if (!draft.trim()) return;
    onNewMessage({ from: 'Maya', text: draft, timestamp: new Date().toISOString(), copilotAssisted: false });
    setDraft('');
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: 'calc(100vh - 60px)', backgroundColor: 'var(--bg)' }}>
      {/* Teams Chat Header */}
      <div style={{ padding: '16px 24px', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', gap: '16px' }}>
        <button onClick={() => onNavigate('teams_home_clr_snapshot')} style={{ background: 'none', border: 'none', cursor: 'pointer' }}><lucide.ArrowLeft size={20} color="var(--text-secondary)" /></button>
        <div style={{ width: '40px', height: '40px', borderRadius: '50%', backgroundColor: 'var(--surface)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <span style={{ fontWeight: 600, color: 'var(--text-secondary)' }}>{alum.name.charAt(0)}</span>
        </div>
        <div>
          <h3 style={{ margin: 0, fontSize: '16px', fontWeight: 600 }}>{alum.name}</h3>
          <p style={{ margin: 0, fontSize: '12px', color: 'var(--text-secondary)' }}>{alum.currentRole} at {alum.currentEmployer}</p>
        </div>
      </div>

      {/* Message List */}
      <div style={{ flex: 1, overflowY: 'auto', padding: '24px', display: 'flex', flexDirection: 'column', gap: '16px' }}>
        {messages.map((msg, i) => {
          const isMe = msg.from === 'Maya';
          return (
            <motion.div key={i} initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', flexDirection: 'column', alignItems: isMe ? 'flex-end' : 'flex-start' }}>
              <div style={{ 
                maxWidth: '70%', padding: '12px 16px', borderRadius: 'var(--radius)',
                backgroundColor: isMe ? 'var(--panel)' : 'var(--surface)',
                border: `1px solid ${isMe ? 'var(--border)' : 'transparent'}`,
                color: 'var(--text-primary)', fontSize: '15px', lineHeight: 1.5
              }}>
                {msg.text}
              </div>
              {msg.copilotAssisted && <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', marginTop: '4px' }}><lucide.Sparkles size={10} style={{ display: 'inline', marginRight: '2px' }}/> Drafted with Copilot</span>}
            </motion.div>
          );
        })}

        {oppDetected && (
          <motion.div initial={{ opacity: 0, scale: 0.95 }} animate={{ opacity: 1, scale: 1 }} style={{ alignSelf: 'center', margin: '16px 0', width: '100%', maxWidth: '400px' }}>
            <Card style={{ borderLeft: '4px solid var(--nu-red)', padding: '16px' }}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '8px', marginBottom: '8px' }}>
                <lucide.Briefcase size={16} color="var(--nu-red)" />
                <span style={{ fontWeight: 600, fontSize: '14px', color: 'var(--nu-red-deep)' }}>Warm Lead Detected</span>
              </div>
              <p style={{ margin: '0 0 12px 0', fontSize: '14px', color: 'var(--text-secondary)' }}>Sarah mentioned hiring at Cordial. Want to flag this for your co-op advisor?</p>
              <Button variant="secondary" label="Flag for Advisor" onClick={() => setOppDetected(false)} />
            </Card>
          </motion.div>
        )}
        <div ref={messagesEndRef} />
      </div>

      {/* Compose Area */}
      <div style={{ padding: '16px 24px', borderTop: '1px solid var(--border)', backgroundColor: 'var(--bg)' }}>
        {suggestions.length > 0 && (
          <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ display: 'flex', gap: '8px', marginBottom: '12px', overflowX: 'auto', paddingBottom: '4px' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '12px', color: 'var(--text-secondary)', fontWeight: 600, marginRight: '8px' }}>
              <lucide.Sparkles size={14} color="var(--nu-red)" /> Suggest a reply
            </div>
            {suggestions.map((s, i) => (
              <button key={i} onClick={() => setDraft(s)} style={{ whiteSpace: 'nowrap', padding: '6px 12px', borderRadius: '16px', border: '1px solid var(--border)', backgroundColor: 'var(--surface)', fontSize: '13px', color: 'var(--text-primary)', cursor: 'pointer' }}>
                {s}
              </button>
            ))}
          </motion.div>
        )}
        <div style={{ display: 'flex', gap: '12px' }}>
          <input 
            type="text" value={draft} onChange={(e) => setDraft(e.target.value)}
            onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Type a new message"
            style={{ flex: 1, height: '44px', padding: '0 16px', borderRadius: 'var(--radius)', border: '1px solid var(--border)', fontSize: '15px', outline: 'none' }}
          />
          <Button label="" icon={lucide.Send} onClick={handleSend} disabled={!draft.trim()} />
        </div>
      </div>
    </div>
  );
};

