// --- MAIN APP ---

const App = () => {
  const [currentScreen, setCurrentScreen] = useState('teams_home_clr_snapshot');
  const [selectedMatch, setSelectedMatch] = useState(null);
  const [ferpaGranted, setFerpaGranted] = useState(false);
  const [messages, setMessages] = useState([]);

  // Inject CSS
  useEffect(() => {
    const style = document.createElement('style');
    style.textContent = `
      @import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono&family=Open+Sans:wght@400;600;700&family=Roboto+Condensed:wght@400;700&display=swap');
      :root {
        --nu-red: #C8102E;
        --nu-red-deep: #9E0A24;
        --nu-red-tint: #FBE7EA;
        --cream: #F8E5C2;
        --bg: #FFFFFF;
        --surface: #F7F7F7;
        --panel: #F0F0F0;
        --text-primary: #000000;
        --text-secondary: #414141;
        --text-tertiary: #737373;
        --border: #D9D9D9;
        --success: #0F8A4B;
        --warning: #B5651D;
        --friction: #9E0A24;
        --font-display: 'Roboto Condensed', sans-serif;
        --font-body: 'Open Sans', sans-serif;
        --font-mono: 'IBM Plex Mono', monospace;
        --radius: 2px;
        --card-radius: 4px;
      }
      body {
        margin: 0;
        font-family: var(--font-body);
        background-color: var(--panel);
        color: var(--text-primary);
        -webkit-font-smoothing: antialiased;
      }
      * { box-sizing: border-box; }
      @keyframes shimmer {
        0% { background-position: 200% 0; }
        100% { background-position: -200% 0; }
      }
    `;
    document.head.appendChild(style);
    return () => document.head.removeChild(style);
  }, []);

  const handleSendIntro = (draftText) => {
    setMessages([{ from: 'Maya', text: draftText, timestamp: new Date().toISOString(), copilotAssisted: true }]);
  };

  const renderScreen = () => {
    switch (currentScreen) {
      case 'teams_home_clr_snapshot':
        return <TeamsHomeCLRSnapshot onNavigate={setCurrentScreen} />;
      case 'trailblazer_shortlist':
        return <TrailblazerShortlist onNavigate={setCurrentScreen} onSelectMatch={setSelectedMatch} />;
      case 'trajectory_detail_modal':
        return <TrajectoryDetailModal match={selectedMatch || SEED_MATCHES[0]} onNavigate={setCurrentScreen} />;
      case 'ferpa_opt_in_modal':
        return <FerpaOptInModal onNavigate={setCurrentScreen} onConsent={() => setFerpaGranted(true)} />;
      case 'copilot_composer':
        return <CopilotComposer match={selectedMatch || SEED_MATCHES[0]} onNavigate={setCurrentScreen} onSend={handleSendIntro} />;
      case 'active_teams_thread':
        return <ActiveTeamsThread match={selectedMatch || SEED_MATCHES[0]} messages={messages} onNewMessage={(m) => setMessages(prev => [...prev, m])} onNavigate={setCurrentScreen} />;
      case 'liz_jen_guardrail_dashboard':
        return <LizJenGuardrailDashboard onNavigate={setCurrentScreen} />;
      default:
        return <div>Screen not found</div>;
    }
  };

  return (
    <div style={{ display: 'flex', height: '100vh', overflow: 'hidden' }}>
      {/* Fake Teams Sidebar */}
      <div style={{ width: '68px', backgroundColor: '#EBEBEB', borderRight: '1px solid var(--border)', display: 'flex', flexDirection: 'column', alignItems: 'center', padding: '16px 0', gap: '24px' }}>
        <div style={{ width: '32px', height: '32px', backgroundColor: '#464EB8', borderRadius: '4px', color: '#FFF', display: 'flex', alignItems: 'center', justifyContent: 'center', fontWeight: 'bold' }}>T</div>
        <lucide.Bell size={24} color="var(--text-secondary)" />
        <lucide.MessageSquare size={24} color="var(--text-secondary)" />
        <div style={{ position: 'relative' }}>
          <lucide.Users size={24} color="var(--nu-red)" />
          <div style={{ position: 'absolute', left: '-20px', top: '50%', transform: 'translateY(-50%)', width: '4px', height: '24px', backgroundColor: 'var(--nu-red)', borderRadius: '0 4px 4px 0' }} />
        </div>
      </div>

      <div style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        {/* Fake Teams Top Nav */}
        <div style={{ height: '60px', backgroundColor: 'var(--bg)', borderBottom: '1px solid var(--border)', display: 'flex', alignItems: 'center', padding: '0 24px', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
            <svg viewBox="0 0 64 53" height={26} fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: "block" }}><path d="M55.9355 15.9871C55.9355 8.40004 58.4903 5.92262 63.6 3.98714V2.70972H46.8774V3.94843C51.9871 5.88391 54.5419 8.36133 54.5419 15.9484V38.2065L19.1226 4.41294C17.4968 2.90327 17.071 2.74843 16.0258 2.74843H2.70969V3.98714C5.65162 4.29681 7.39356 5.10972 11.6129 9.21294L13.2387 10.7613V36.1549C13.2387 43.742 10.6839 46.2194 5.5742 48.1549V49.3936H22.2968V48.1549C17.1871 46.2194 14.6323 43.742 14.6323 36.1549V11.9226L54.6968 49.6646H55.9355V15.9871Z" fill="#C8102E" /></svg>
            <h1 style={{ margin: 0, fontSize: '16px', fontWeight: 600 }}>Khoury Class of 2028 <span style={{ color: 'var(--text-tertiary)', fontWeight: 400, margin: '0 8px' }}>|</span> Trailblazer Match</h1>
          </div>

          {/* Demo Controls */}
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <select 
              value={currentScreen} 
              onChange={(e) => setCurrentScreen(e.target.value)}
              style={{ padding: '4px 8px', borderRadius: 'var(--radius)', border: '1px solid var(--border)', fontSize: '12px' }}
            >
              <option value="teams_home_clr_snapshot">1. CLR Snapshot</option>
              <option value="trailblazer_shortlist">2. Shortlist</option>
              <option value="trajectory_detail_modal">3. Trajectory Detail</option>
              <option value="ferpa_opt_in_modal">4. FERPA Opt-In</option>
              <option value="copilot_composer">5. Copilot Composer</option>
              <option value="active_teams_thread">6. Active Thread</option>
              <option value="liz_jen_guardrail_dashboard">7. Guardrail Dashboard</option>
            </select>
            <Button variant="secondary" label="Reset" onClick={() => { setCurrentScreen('teams_home_clr_snapshot'); setMessages([]); setFerpaGranted(false); }} style={{ height: '28px', padding: '0 12px', fontSize: '12px' }} />
          </div>
        </div>

        {/* Main Content Area */}
        <div style={{ flex: 1, overflowY: 'auto', position: 'relative' }}>
          <AnimatePresence mode="wait">
            <motion.div
              key={currentScreen}
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.2 }}
              style={{ minHeight: '100%' }}
            >
              {renderScreen()}
            </motion.div>
          </AnimatePresence>
        </div>
      </div>
    </div>
  );
};

function __test_state_transitions__() {
  return typeof App === 'function';
}
if (typeof window !== 'undefined') {
  window.__hicProtoTests = __test_state_transitions__;
}
